using namespace std;

const int MAXN = 105;
int d, n;
vector<int> a, e, r;
vector<vector<int>> memo;
const int INF = 1000000000;

inline void rec(int exp, int end, int c) {
    if (memo[exp][end] <= c) return;
    memo[exp][end] = c;

    for (int i = 0; i < n; i++) {
        if (exp < r[i]) continue;
        rec(min(exp + e[i], 100), max(end - a[i], 0), c + 1);
    }
}

