        memo = vector<vector<int>>(MAXN, vector<int>(MAXN, INF));
        rec(0, d, 0);
        int ans = INF;
        for (int i = 0; i < 101; i++) ans = min(ans, memo[i][0]);
        printf("%s\n", ans == INF ? "NA" : to_string(ans).c_str());
    }
    return 0;
}

