#include <queue>
#include <cstdio>
using namespace std;

const int MAX_EXP = 105;
const int MAX_END = 105;
int d, n;
vector<int> a, e, r;
int memo[MAX_EXP][MAX_END];
const int INF = 1000000000;

void iterative() {
    queue<pair<int, pair<int, int>>> q;
    q.push({0, {0, d}});

    while (!q.empty()) {
        auto [c, exp_end] = q.front();
        int exp = exp_end.first;
        int end = exp_end.second;
        q.pop();

        if (memo[exp][end] <= c) continue;
        memo[exp][end] = c;

        for (int i = 0; i < n; i++) {
            if (exp < r[i]) continue;
            q.push({c + 1, {min(exp + e[i], 100), max(end - a[i], 0)}});
        }
    }
}

int main() {
    while (scanf("%d %d", &d, &n), d) {
        a.resize(n);
        e.resize(n);
        r.resize(n);
        for (int i = 0; i < n; i++) scanf("%d %d %d", &a[i], &e[i], &r[i]);
        fill(&memo[0][0], &memo[0][0] + sizeof(memo) / sizeof(int), INF);
        iterative();
        int ans = INF;
        for (int i = 0; i < 101; i++) ans = min(ans, memo[i][0]);
        printf("%s\n", ans == INF ? "NA" : to_string(ans).c_str());
    }
    return 0;
}
